export const GUIDE_TASKS: GuideTask[] = [
  { title: "Find what uses the most energy", steps: ["Open Facility → Devices.", "“What stands out” names the biggest single user and what it cost.", "“Where the energy goes” ranks every device with its share and cost. Click a name to open that device."] },
  { title: "See what is left on after working hours", steps: ["Open Analysis and go to step 3, “What stays on after working hours”.", "Or open Facility → Devices and look at the heatmap: red or orange cells under “After working hours” mean the device is running while the site is closed.", "Items marked “Check first” may need to run all the time, such as fridges or servers."] },
  { title: "Look at one board or one device", steps: ["Open Facility → Devices.", "Under Show, pick a board (for example DB2) to see everything on that board only.", "Or choose Open a device and search for it. Use Previous and Next to step through devices.", "Each view has its own link, so you can copy the address and share it."] },
  { title: "Check a single day, such as a holiday", steps: ["Open Analysis, go to step 2 and choose Single day.", "Click the date to open the calendar. Weekends are shaded, holidays are orange and days with missing readings have a dashed border.", "The chart shows that day hour by hour, with working hours unshaded."] },
  { title: "Understand a peak", steps: ["Open Analysis and find Peak 1h Consumption in the Executive Summary.", "Choose View top 5 to see the busiest hours.", "The breakdown shows each space's share and, for the selected space, a chart of which circuits used the energy."] },
  { adminOnly: true, title: "Update the electricity rate", steps: ["Open Facility → Electricity rate and choose Edit, or Add next rate in the warning.", "Enter the price per kWh and the dates exactly as they appear on your bill, and whether the price is before or including GST.", "Choose Save rate. Every cost figure in the app uses it straight away."] },
  { adminOnly: true, title: "Change operating hours or add a holiday", steps: ["Operating hours: open Facility → Operating hours, choose Edit, set the hours for each day and save.", "Holidays: open Facility → Holidays, click a day or drag across several, choose the type and save.", "Saving updates reports and charts straight away."] },
  { adminOnly: true, title: "Set lights-on hours for lighting that runs at night", steps: ["Open Facility → Operating hours and choose Edit.", "Under What the hours mean, choose Lights-on hours.", "Set the hours for every day. For hours past midnight, set an end earlier than the start, for example 19:00 to 07:00.", "Choose Save changes. Use outside these hours now counts as daytime use, and weekends, holidays and closures keep the same hours. The Overview warns when daytime use reaches 10% of the total."] },
  { adminOnly: true, title: "Group meters and give them short names", steps: ["Open Facility → Floor layout. The Groups list is on the left.", "Choose + New group to add a group. Select a group to Rename it, add + Group inside (for example floors inside a block), or Remove it once its meters have moved out.", "Drag a meter onto a group, or choose Move to… beside the meter. The first time a meter moves, the name of its old group is kept as its Electrical panel. A new group goes live once it has a meter in it.", "For a shorter name, choose Edit on the meter and fill in Short name. It shows first everywhere, with the full name underneath. Where two meters would look the same, put the block in front, for example Block A Lift lobby.", "Totals and shares in reports, Devices and Analysis come from these groups, and the Overview shows each top-level group's share."] },
  { adminOnly: true, title: "Arrange groups from a spreadsheet", steps: ["Open Facility → Floor layout and choose Arrange from a spreadsheet, below + New group.", "Choose an Excel (.xlsx) or CSV file with one row per meter. Download a template shows the columns: Group (use > for a group inside a group, for example Common area > Pavilion), Meter name and an optional Short name. The file stays on this computer.", "Check the columns, then the meters. Each row is matched to a meter: check any best guesses, and pick a meter or choose Skip this row for any that did not match.", "What will change lists the new groups, the meters that move and the short names. Groups left with no meters are removed unless you untick Remove them. No meters are removed.", "Optional: tick Also add a floor-plan area for each top-level group. Then choose Apply these groups. Nothing changes until you do."] },
  { adminOnly: true, title: "Draw the floor plan and place devices", steps: ["Open Facility → Floor layout and choose Edit layout (on a new site, Draw the layout).", "Choose + Add area, + Add room or + Add equipment inside a room, then drag a box on the plan to draw it (a single click adds one at the usual size; Esc stops). Drag items to move them and pull a corner or the middle of an edge to resize. Pull any edge of the drawing space, left and top included, to make it bigger. + Add entrance shows where people come in.", "To work on several items at once, Shift-click them or drag a box across empty space (inside an area, hold Shift while dragging); they move, nudge and delete together. Duplicate (or ⌘/Ctrl+D) copies an area with its rooms and equipment, and ⌘/Ctrl+C then ⌘/Ctrl+V pastes copies; devices are never copied, and a copy has no panel until you pick one. Lock in place stops an item being moved or deleted by accident. Bring to front and Send to back choose which overlapping item is drawn on top.", "For exact placing, open Grid in the toolbar: turn snapping on or off, choose the grid spacing, or hide the grid. While snapping is on, a dragged item also lines up with the edges and centres of nearby items (a thin guide line shows it); hold ⌘/Ctrl while dragging to place it freely. With one item selected, type its X, Y, Width and Height under Position and size and press Enter. With several selected, Line up aligns their edges or centres, spaces them evenly, or gives them the same width or height. Colour has ten swatches or your own colour code, and for an area on a panel, Colour for everything on this panel colours that panel's areas, rooms and devices at once (unless one has its own colour).", "Choose “Place the rest in their board's area”: each device goes to the room its name mentions. Drag any device to its exact spot.", "Under Plan style, choose how the plan looks for everyone: Building drawing, Blueprint or Colour blocks; How it will look shows it as you go. Then choose Save layout. The plan updates straight away, including in Project notes and for the advisor.", "Undo and Redo fix mistakes, also with the keys right after clicking a button; for arrows and Delete, click the plan first. Holding an arrow down is one step to undo. Choosing Cancel or another Facility tab with changes not saved asks before leaving. Areas the saved layout holds without a place on the drawing are listed under Not on the drawing and kept as they are."] },
  { adminOnly: true, title: "Set up a new site from data files", steps: ["Click the project name at the top left. Choose New client and enter the company's name (skip this if the client already exists).", "Choose New project, enter the site's name and timezone, then open the new project.", "Open Facility and choose Upload data. Drag the meter files (CSV or Excel exports from the meter app) into the box.", "Under “Check device names”, choose Add or change names: paste the device table from Excel, load a CSV, or choose Read from a photo of the table.", "Check the table, then choose Set up & publish. A distribution board, one group per device and the meter names are created, and the readings go live.", "Optional: set Operating hours and the Electricity rate so after-hours use and costs are worked out."] },
  { adminOnly: true, title: "Add new data each month", steps: ["Export the latest readings from the meter app as CSV or Excel.", "Open Facility → Upload data and drag the file in. Each file shows which dates are new; dates already loaded are not counted twice.", "Choose Publish. “Published” shows the new date range, the readings added and any new devices.", "Keep device names the same in the meter app: a renamed device appears as a new one."] },
  { adminOnly: true, title: "Set up a new site from Tuya (no file)", steps: ["Create the client and the site (New client, then New project), then open the new project.", "Open Facility and choose Live connection. Under Start from Tuya, enter the Tuya cloud project's Access ID and Access Secret and choose Connect. They are on platform.tuya.com: Cloud → Open Project → Overview tab → Authorization Key.", "The box at the top shows the connection and what Tuya holds: all devices, the ones that can be meters (online and offline), gateways, and how many are ticked. Refresh list asks Tuya again. One Tuya account can hold several sites' devices; a device another site already reads is marked Connected to another site and left unticked.", "With the site's own sheet (best): choose Paste your device list. In Excel, select from the heading row down to the last meter, copy, and paste. Headings such as Block Number, Meter Name, Meter Device ID and Meter Tracking Location are understood; a row with only a block (for example 264F) sets the block for the meters below it, and other columns, such as daily readings, are ignored. Or choose Load an Excel or CSV file and pick the sheet itself (.xlsx): a title row above the headings and notes below the meters are skipped.", "Choose Check the list. Each line shows Found, or why not (for example Not in this Tuya account: a wrong ID, or the app account that holds it is not linked to the cloud project). Fix those lines and check again.", "Choose Connect … meters and fetch the last 7 days. Only the meters on the sheet are connected. They get the sheet's names; a name used in more than one block gets the block in front (for example 264F Emergency Lighting). What each one tracks is kept, Floor layout groups the meters by block, the last 7 days come in, and the site then updates every day at 02:00.", "No sheet? Choose Tick devices from Tuya's list. Search by name, device type or online / offline, or paste device IDs (one or a whole column from Excel): the list shows just those devices, names any ID Tuya does not have, and Tick only these ticks exactly them. Untick anything that is not this site's meter, then choose Create … meters.", "Tuya keeps only about 7 days of readings, so connect a new site within a week of installing its meters. To draw the site afterwards, see Draw the floor plan and place devices."] },
  { adminOnly: true, title: "Connect meters for live data (Tuya)", steps: ["For a site whose meters are already set up from data files or with the advisor. A new site with no meters can start from Tuya instead (see Set up a new site from Tuya).", "Open Facility and choose Live connection. Enter the Tuya cloud project's Access ID and Access Secret and choose Connect. The key is stored encrypted and never shown again.", "Match each meter to its Tuya device: choose Match by name, then pick any that are left from the list, and choose Save matches.", "Choose Check devices to confirm every device sends energy readings.", "Tick Update every day and pick the hour. Choose Fetch now to bring in the last week straight away.", "A site managed by EnergyX support (Tuya Office) shows its devices read-only. To edit it yourself, enter the same Access ID and Access Secret under Manage this site here instead and choose Manage here; Let support manage it hands it back.", "A meter that only has power while its lights are on (for example outdoor or linkway lights on a timer) goes offline every day while they are off. Open Facility → Floor layout, choose Edit on that meter and tick Turns off with its lights: it then shows Off with the lights instead of Device offline, and counts as offline, with an alert email, only after 16 hours."] },
  { adminOnly: true, title: "Add new meters to a site on Tuya", steps: ["Open Facility → Live connection and choose Add new meters, in the step that matches each meter to its device.", "The list shows devices in the Tuya project that are not in this site yet. Tick the new ones, check each name and choose its group under Goes in. Tick Off with the lights for a meter that only has power while its lights are on.", "Choose Add … meters. This can take a minute. Readings arrive with the next daily update, or choose Fetch now."] },
  { adminOnly: true, title: "Add a client, or move or remove a project", steps: ["Click the project name at the top left to open the project list.", "New client adds a client. To move a project, drag it onto another client, or hover it and choose ⋯ → Move to another client.", "⋯ also offers Archive, which hides the project from the client but keeps its data, and Delete permanently, which needs the project's name typed to confirm."] },
  { title: "Create a report from the meter readings", steps: ["Open Reports and choose Create a report.", "Under From your meter readings, pick the dates (up to three months at a time).", "Choose a Style. Full report has every chart, table and check. Management review is short and plain, organised by group, with the things worth deciding.", "Choose Create report. It is written in a few seconds, with no AI, and saved in Reports. Administrators can set the style of weekly and monthly reports with Site report style in Automatic reports."] },
  { title: "Get a report or an answer", steps: ["Open Energy advisor → Ask the advisor.", "Type your question in plain English and send it.", "Finished reports are kept in Reports.", "Reports every week or month (admins): open Reports → Automatic reports, choose how often, the hour and what each report should cover, then Save schedule. The site first needs a saved report method: after a report you like, choose Save report method and make it the site's default in Advisor guidelines."] },
];

export const GUIDE_CHARTS: GuideTerm[] = [
  { term: "Daily bars", meaning: "One bar per day. A grey strip under the axis marks a closed day. PH is a public holiday, PC a planned closure and SH a day with special hours." },
  { term: "Typical day", meaning: "Average power for each hour of the day. The shaded band shows operating hours." },
  { term: "Heatmap", meaning: "Each cell is one hour. The colour shows how hard the device was working compared with its busiest hour: green is low, red is high. The band above shows operating hours and after working hours." },
  { term: "Every day, hour by hour", meaning: "On a single device, one row per day. All days use the same scale, so a busy day and a quiet day can be compared directly." },
  { term: "Floor plan", meaning: "Each colour is one distribution board. Pins are devices; the label leaves out the room name it sits in. Faded areas are not part of your selection." },
  { term: "Peak breakdown chart", meaning: "How one space's energy split between circuits in that hour. The grey “Not split by circuit” slice is energy the main meters recorded but no circuit meter explains." },
];

export const GUIDE_TERMS: GuideTerm[] = [
  { term: "kWh", meaning: "Energy used over time, and what the bill charges for. A 1 kW load running for one hour uses 1 kWh." },
  { term: "kW", meaning: "Power at a moment: how hard equipment is working right then." },
  { term: "Peak demand", meaning: "The highest 15-minute average power in the period." },
  { term: "Always-on load", meaning: "The power drawn in at least 9 of every 10 hours. It runs whether or not anyone is there." },
  { term: "After working hours", meaning: "Energy used outside the operating hours, including weekends, public holidays and planned closures." },
  { term: "Operating hours", meaning: "When the site is open, set in Facility → Operating hours." },
  { term: "Distribution board (DB)", meaning: "The electrical panel that feeds an area. Each board has its own meters." },
  { term: "Board total", meaning: "A meter that measures a whole board, such as all lighting on DB1. It overlaps the devices on that board, so it is not added to them." },
  { term: "No separate meter", meaning: "Energy a board recorded that no individual device meter explains. Extra metering there would show where it goes." },
  { term: "Readings received", meaning: "The share of expected readings that arrived. Below 95%, totals may be a little low." },
  { term: "Group", meaning: "Meters that serve the same thing, such as a block, a floor or a common area. Set in Facility → Floor layout. Totals and shares come from groups." },
  { term: "Short name", meaning: "A shorter name for a meter. It shows first everywhere, with the full name underneath." },
  { term: "Lights-on hours", meaning: "The hours lighting should run, set in Facility → Operating hours instead of opening hours. Use outside them counts as daytime use." },
  { term: "Usual day", meaning: "The middle value of the complete days in the chosen dates; it needs at least five. A day stands out when it differs from this by more than 3% and by more than twice the normal day-to-day variation." },
  { term: "Planned closure", meaning: "A day the site is closed on purpose, such as a company shutdown." },
  { term: "Special hours", meaning: "A day with opening hours different from the usual week." },
  { term: "Saving a change", meaning: "Changes you save in Facility apply across the app straight away. If one cannot go live, the Facility page says why and offers Make live now." },
  { term: "Yearly estimate", meaning: "The average day in the period multiplied by 365. A guide, not a forecast." },
  { term: "Savings range", meaning: "The lower figure assumes equipment only drops to its quietest nights; the higher figure assumes it is switched off whenever the site is closed." },
];

export const GUIDE_QUESTIONS: GuideQuestion[] = [
  { question: "Is the data live?", answer: "No. Readings are collected once a day for the previous full day, so pages show the newest complete days. Reload a page to pick up new data." },
  { question: "Why do some days look empty or low?", answer: "Some devices sent no readings, or only some, on those days. They are marked “Readings missing” or with a dashed border, and totals for them may be low." },
  { question: "Why don't the devices add up to the site total?", answer: "Board totals overlap with the devices on them, and some energy has no separate meter. “Where the energy goes” on Devices splits it so the list adds up to the total." },
  { question: "I changed a setting but nothing moved.", answer: "Changes you save in Facility apply straight away, so reload the page you are looking at. If the Facility page says some changes are not live yet, it shows why; choose Make live now to try again." },
  { question: "Do the days before a site was connected count as missing?", answer: "No. A new site is counted from its first reading. Hours when a meter reported no use, such as a light that is off by day, count as received. A meter marked Not in use does not stop a day counting as complete in reports." },
  { question: "Who can change settings?", answer: "Administrators can edit rates, hours, holidays, groups and the floor plan. Everyone else can view every page." },
  { question: "Can I switch to dark mode?", answer: "Yes. Use the sun and moon switch in the top bar. Your choice is remembered on this browser." },
];

